WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_multiple_base'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '基期倍数', 'kp-xingce-data-multiple-base', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "基期倍数"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "倒推上一年度 A 是 B 的倍数关系。公式与基期比重、基期平均数完全一致！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题目给出今年 A 和 B 的数据及各自增速，问：“2022年，A 是 B 的多少倍？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "katexBlock", "attrs": {"content": "基期倍数 = \\frac{A}{B} \\times \\frac{1+b}{1+a}"}}, {"type": "paragraph", "content": [{"type": "text", "text": "（没错，资料分析三大基期问题，用的是一模一样的通解公式和两步秒杀法）"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[列出拆解公式] --> B[第一步: 算出今年的倍数 A/B]\nB --> C[第二步: 比较 A的增速a 和 B的增速b]\nC -- a > b --> D[说明今年倍数被拉大了, 去年(基期)必定小于今年!]\nC -- a < b --> E[说明今年倍数被压缩了, 去年(基期)必定大于今年!]\nD --> F[在选项中锁定方向正确的数据]\nE --> F"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2023年棉花产量 800 万吨，增 10%(a)。大豆产量 200 万吨，增 25%(b)。问2022年棉花产量是大豆的多少倍？选项：A. 3.2  B. 4.0  C. 4.5  D. 5.1"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算现期：今年的倍数 A/B = 800 / 200 = 4 倍。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "看微调：棉花增速 a(10%) < 大豆增速 b(25%)。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "定方向：分母长得快，去年的倍数一定比今年大（选大于 4 的）。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "锁定选项：C (4.5) 和 D (5.1) 中挑一个。因为 a 和 b 差距还算大，基期会比 4 大出一段距离，选 C 验证。精确算 4 × 1.25 / 1.1 ≈ 4.5。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "重蹈覆辙算基期量：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "不要去算出棉花的基期量（800/1.1），再去算出大豆的基期量（200/1.25），然后再去把这两个难看的数字相除。浪费时间就是谋杀自己。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "将“基期比重”、“基期平均数”、“基期倍数”三类题型混在一起刷，建立大一统的“现期估算+增速微调”条件反射。"}]}]}$$ AS jsonb), NULL, '基期倍数的核心考点与实战推导。', category_node.id, CAST('["资料分析", "基期倍数"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_multiple_base", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
